def histogram(test):
    if not test:
        return {}

    words = test.split()
    word_count = {}
    max_count = 0

    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1
        max_count = max(max_count, word_count[word])

    return {word: count for word, count in word_count.items() if count == max_count}

