def get_odd_collatz(n):
    def collatz_sequence(num):
        sequence = []
        while num != 1:
            sequence.append(num)
            if num % 2 == 0:
                num = num // 2
            else:
                num = 3 * num + 1
        sequence.append(1)
        return sequence

    odd_numbers = [num for num in collatz_sequence(n) if num % 2 != 0]
